From 026283d0094af10bb27c70a275d9b20104d3928e Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:24:50 +0100
Subject: [PATCH] emergencywindow: suggest Ctrl+Alt+F3 to reach a text console

The broken locker message suggested switching to VT 1 or 2, but those
usually hold the display manager or the graphical session, so users got
a frozen or empty screen. Suggest VT 3 instead, or 4 if we run on it.

BUG: 473247
---
 emergencywindow.cpp | 4 ++--
 1 file changed, 2 insertions(+), 2 deletions(-)

diff --git a/emergencywindow.cpp b/emergencywindow.cpp
index 8dae42e3..e49a1f9c 100644
--- a/emergencywindow.cpp
+++ b/emergencywindow.cpp
@@ -74,11 +74,11 @@ void EmergencyWindow::paintEvent(QPaintEvent *)
     };
     if (haveService(QStringLiteral("org.freedesktop.ConsoleKit"))) {
         auto virtualTerminalId = qgetenv("XDG_VTNR").toInt();
-        text = text_ck.subs(virtualTerminalId == 2 ? 1 : 2);
+        text = text_ck.subs(virtualTerminalId == 3 ? 4 : 3);
     } else if (haveService(QStringLiteral("org.freedesktop.login1"))) {
         text = text_ld;
         auto virtualTerminalId = qgetenv("XDG_VTNR").toInt();
-        text = text.subs(virtualTerminalId == 2 ? 1 : 2);
+        text = text.subs(virtualTerminalId == 3 ? 4 : 3);
         text = text.subs(QString::fromLocal8Bit(qgetenv("XDG_SESSION_ID")));
         text = text.subs(virtualTerminalId);
     }
-- 
